        MXLog.error("Failed retrieving deviceID with error: \(error)")
        return nil
    }
}

var homeserver: String {
    client.homeserver()
}

var canDeactivateAccount: Bool {
    client.canDeactivateAccount()
}

var userIDServerName: String? {
    do {
        return try client.userIdServerName()
    } catch {
